t": true}, "primary_location": {"id": "doi:10.3390/gels11080619", "doi": "https://doi.org/10.3390/gels11080619", "is_oa": true, "landing_page_url": "https://doi.org/10.3390/gels11080619", "pdf_url": "https://www.mdpi.com/2310-2861/11/8/619/pdf?version=1754650087", "source": {"id": "https://openalex.org/S2737559645", "display_name": "Gels", "issn_l": "2310-2861", "issn": ["2310-2861"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["cwts-core", "doaj", "norway-1", "poland-20", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310310987", "host_organization_name": "Multidisciplinary Digital Publishing Institute", "host_organization_lineage": ["https://openalex.org/P4310310987"], "host_organization_lineage_names": ["Multidisciplinary Digital Publishing Institute"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Gels", "raw_type": "journal-article"}, "abstract": "Electroconductive, self-healing hydrogels have surfaced as a versatile tool for advanced wound care applications, since they combine classic hydrogels' moist and biomimetic environment with the dynamic electrical responsiveness that can function as an accelerator of tissue repair processes. Recent advances report the automatic restoration of materials after mechanical disruption through various mechanisms, such as ionic or covalent bonds and supramolecular interactions. This property is crucial for biomaterials, as they are often applied in skin regions with high motility and, therefore, a high risk of breakage. By integrating within these networks compounds that are electrically active-polymers such as PEDOT:PSS or polypyrrole, or 2D nanomaterials such as graphene-it is possible to confer responsiveness to these hydrogels, which can lead to increases in fibroblast proliferation, antimicrobial properties, and angiogenesis. Furthermore, these biomaterials must have skin-mimicking mechanical properties and can also be loaded with drugs to improve their healing properties even further. This review synthesizes the chemistry behind the self-healing and electroconductive properties of these materials and expands on the available literature on this field and their biological outcomes, while also providing a look into the future of these promising materials, aiming at their integration in standard wound care strategies."}]", "excerpt_truncated": true, "source_sha256": "06c936f50ad9cdf1414631e2618073f65db3bc3fa32d779909dc84c1bd403999", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1039/c5cs00194c", "doi:10.3390/gels11080619", "openalex:W2145761747"], "source_candidates": ["https://doi.org/10.1039/c5cs00194c", "https://pubs.rsc.org/en/content/articlepdf/2015/cs/c5cs00194c", "https://doi.org/10.3390/gels11080619"], "source_candidate_identities": {}}
